function ex(s){ return String(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }

// hp:t 텍스트만 교체 (구조 유지)
function setT(xml, ps, pe, text){
  return xml.slice(0,ps) + "<hp:t>" + ex(text) + "</hp:t>" + xml.slice(pe);
}

// 템플릿의 마지막 hp:t 교체
function setLastT(tpl, text){
  const ms = [...tpl.matchAll(/<hp:t>[^<]*<\/hp:t>/g)];
  if(!ms.length){
    // 자기닫힘 run 태그: <hp:run .../> → <hp:run ...><hp:t>text</hp:t></hp:run>
    const runMatch = tpl.match(/<hp:run[^>]*\/>/);
    if(runMatch){
      const sc = tpl.lastIndexOf(runMatch[0]);
      const ins = runMatch[0].slice(0,-2)+"><hp:t>"+ex(text)+"</hp:t></hp:run>";
      return tpl.slice(0,sc)+ins+tpl.slice(sc+runMatch[0].length);
    }
    const ri = tpl.lastIndexOf("</hp:run>");
    return ri<0 ? tpl : tpl.slice(0,ri)+"<hp:t>"+ex(text)+"</hp:t>"+tpl.slice(ri);
  }
  const l = ms[ms.length-1];
  return tpl.slice(0,l.index)+"<hp:t>"+ex(text)+"</hp:t>"+tpl.slice(l.index+l[0].length);
}

// 현안이슈 XML 생성
function makeIssues(issues, t14, t89){
  if(!issues||!issues.length) return setLastT(t14,"(해당 없음)");
  return issues.map(iss=>{
    const ts=[...t14.matchAll(/<hp:t>[^<]*<\/hp:t>/g)];
    const p = ts.length>=2
      ? t14.slice(0,ts[ts.length-1].index)+"<hp:t>"+ex(iss.project||"")+"</hp:t>"+t14.slice(ts[ts.length-1].index+ts[ts.length-1][0].length)
      : setLastT(t14,"  ○ "+(iss.project||""));
    // 항목+세부 쌍으로 출력 (항목[i] 다음에 세부[i])
    const {t88} = TPL;
    const itemsXml = (iss.items||[]).map((it,i)=>{
      const ts2=[...t89.matchAll(/<hp:t>[^<]*<\/hp:t>/g)];
      const itemLine = ts2.length>=2
        ? t89.slice(0,ts2[ts2.length-1].index)+"<hp:t>"+ex(it)+"</hp:t>"+t89.slice(ts2[ts2.length-1].index+ts2[ts2.length-1][0].length)
        : setLastT(t89,it);
      // 해당 항목의 세부가 있으면 바로 아래에 출력
      const det = iss.details && iss.details[i];
      const detLine = det ? setLastT(t88,"      ㆍ"+det) : "";
      return itemLine + detLine;
    }).join("");
    return p+itemsXml;
  }).join("");
}

// ZIP에서 파일 읽기
function readZip(zipBuf, filename){
  const v = new DataView(zipBuf.buffer || zipBuf);
  let o=0;
  while(o<zipBuf.length-4){
    if(v.getUint32(o,true)!==0x04034b50) break;
    const mt=v.getUint16(o+8,true), cs=v.getUint32(o+18,true);
    const nl=v.getUint16(o+26,true), xl=v.getUint16(o+28,true);
    const fn=zipBuf.slice(o+30,o+30+nl).toString("utf-8");
    const dOff=o+30+nl+xl;
    if(fn===filename){
      const raw=zipBuf.slice(dOff,dOff+cs);
      return mt===8 ? zlib.inflateRawSync(raw) : raw;
    }
    // flag&8: 데이터 디스크립터 건너뛰기
    let nextO2=dOff+cs;
    if(mt===8 && (zipBuf[o+6]&8)){
      if(v.getUint32(nextO2,true)===0x08074b50) nextO2+=4;
      nextO2+=12;
    }
    o=nextO2;
  }
  return null;
}

// ZIP에서 파일 교체
// ZIP 파일에서 특정 파일 교체 - 모든 파일 비압축(STORED) 방식
function patchZip(zipBuf, filename, newXmlStr) {
  const newData = Buffer.from(newXmlStr, "utf-8");
  const newCrc = crc32(newData);
  const parts = [], cdEntries = [];
  let offset = 0;
  const v = new DataView(zipBuf.buffer || zipBuf);
  let o = 0;
  while (o < zipBuf.length - 4) {
    const sig = v.getUint32(o, true);
    if (sig !== 0x04034b50) break;
    const mt = v.getUint16(o+8, true);
    const crc = v.getUint32(o+14, true);
    const cs = v.getUint32(o+18, true);
    const nl = v.getUint16(o+26, true);
    const xl = v.getUint16(o+28, true);
    const fn = zipBuf.slice(o+30, o+30+nl).toString("utf-8");
    const dOff = o+30+nl+xl;
    // 원본 압축 해제 후 비압축으로 저장
    const compData = zipBuf.slice(dOff, dOff+cs);
    const rawData = (fn === filename) ? newData : ((mt === 8) ? zlib.inflateRawSync(compData) : compData);
    const fileCrc = (fn === filename) ? newCrc : crc32(rawData);
    const fileSize = rawData.length;
    // 로컬 헤더 (STORED)
    const hdr = Buffer.alloc(30+nl);
    hdr.writeUInt32LE(0x04034b50,0); hdr.writeUInt16LE(20,4); hdr.writeUInt16LE(0,6);
    hdr.writeUInt16LE(0,8); hdr.writeUInt16LE(0,10); hdr.writeUInt16LE(0,12);
    hdr.writeUInt32LE(fileCrc,14); hdr.writeUInt32LE(fileSize,18); hdr.writeUInt32LE(fileSize,22);
    hdr.writeUInt16LE(nl,26); hdr.writeUInt16LE(0,28);
    zipBuf.copy(hdr,30,o+30,o+30+nl);
    cdEntries.push({fn,nl,crc:fileCrc,size:fileSize,off:offset});
    parts.push(hdr); parts.push(rawData);
    offset += hdr.length + rawData.length;
    o = dOff + cs;
  }
  const cdBufs = cdEntries.map(e => {
    const cd = Buffer.alloc(46+e.nl);
    cd.writeUInt32LE(0x02014b50,0); cd.writeUInt16LE(20,4); cd.writeUInt16LE(20,6);
    cd.writeUInt16LE(0,8); cd.writeUInt16LE(0,10); cd.writeUInt16LE(0,12); cd.writeUInt16LE(0,14);
    cd.writeUInt32LE(e.crc,16); cd.writeUInt32LE(e.size,20); cd.writeUInt32LE(e.size,24);
    cd.writeUInt16LE(e.nl,28); cd.writeUInt16LE(0,30); cd.writeUInt16LE(0,32);
    cd.writeUInt16LE(0,34); cd.writeUInt16LE(0,36); cd.writeUInt32LE(0,38); cd.writeUInt32LE(e.off,42);
    Buffer.from(e.fn).copy(cd,46); return cd;
  });
  const cdBuf = Buffer.concat(cdBufs);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50,0); eocd.writeUInt16LE(0,4); eocd.writeUInt16LE(0,6);
  eocd.writeUInt16LE(cdEntries.length,8); eocd.writeUInt16LE(cdEntries.length,10);
  eocd.writeUInt32LE(cdBuf.length,12); eocd.writeUInt32LE(offset,16); eocd.writeUInt16LE(0,20);
  return Buffer.concat([...parts, cdBuf, eocd]);
}

function crc32(buf){
  if(!crc32._t){
    crc32._t=new Uint32Array(256);
    for(let i=0;i<256;i++){let c=i;for(let j=0;j<8;j++)c=c&1?(0xEDB88320^(c>>>1)):(c>>>1);crc32._t[i]=c;}
  }
  let c=0xFFFFFFFF;
  for(let i=0;i<buf.length;i++)c=(c>>>8)^crc32._t[(c^buf[i])&0xFF];
  return (c^0xFFFFFFFF)>>>0;
}


// schedule detail 셀 lineseg 동적 생성
function makeLineSeg(text){
  let len=0;
  for(const c of (text||'')) len+=(c.charCodeAt(0)>127)?2:1;
  const CHARS=52, VERT=1100, SPACING=332, STRIDE=VERT+SPACING;
  const lines=Math.max(1,Math.ceil(len/CHARS));
  let segs='';
  for(let i=0;i<lines;i++) segs+=`<hp:lineseg textpos="0" vertpos="${i*STRIDE}" vertsize="${VERT}" textheight="${VERT}" baseline="935" spacing="${SPACING}" horzpos="0" horzsize="31492" flags="393216"/>`;
  return `<hp:linesegarray>${segs}</hp:linesegarray>`;
}
// schedule detail linesegarray 위치 (원본 XML 기준)
const SCHED_LSA=[
  [[23179,23358]],   // 행1: linesegarray 1개
  [[25953,26132]],   // 행2
  [[28401,28580]],   // 행3
  [[30826,31005]],   // 행4
  [],                // 행5
  [],                // 행6
];

function buildHWPX(data){
  const origBuf = Buffer.from(ORIG_B64,"base64");
  let xml = readZip(origBuf,"Contents/section0.xml").toString("utf-8");

  // 모든 교체를 뒤→앞 순서로 한번에
  const reps = [];

  // 0. 날짜 교체
  if(data.date){
    reps.push([DATE_T[0], DATE_T[1], "<hp:t>("+ex(data.date)+")</hp:t>"]);
  }

  // 1. 주요일정 (hp:t 및 자기닫힘 run 모두 처리)
  const sc = data.schedule||[];
  for(let i=0;i<6;i++){
    const s = sc[i]||{date:"",detail:"",note:""};
    const vals = [s.date||"", s.detail||"", s.note||""];
    // detail 텍스트 길이에 따라 lineseg 동적 교체
    if(SCHED_LSA[i] && vals[1]){
      SCHED_LSA[i].forEach(([ls,le])=>{ reps.push([ls,le,makeLineSeg(vals[1])]); });
    }
    (CELL_INFO[i]||[]).forEach((cell, ci)=>{
      const val = ci<vals.length ? vals[ci] : "";
      if(cell.type==="t"){
        (cell.pos||[]).forEach(([ps,pe],ti)=>{
          if(ti===0){
            reps.push([ps, pe, "<hp:t>"+ex(val)+"</hp:t>"]);
          } else {
            // 두 번째 이후 hp:t는 완전 삭제 (공간 차지 방지)
            reps.push([ps, pe, ""]);
          }
        });
      } else if(cell.type==="sc"){
        // 자기닫힘 run → hp:t 포함 run으로 교체
        const newRun = cell.r.slice(0,-2)+"><hp:t>"+ex(val)+"</hp:t></hp:run>";
        reps.push([cell.s, cell.e, newRun]);
      }
    });
  }

  // 2. 공공사업
  const bd = data.biz_details||[];
  const bizXml = bd.length>0
    ? bd.map(b=>setLastT(TPL.t75,"    - "+(b.name||""))+(b.details||[]).map(d=>setLastT(TPL.t88,"      ㆍ"+d)).join("")).join("")
    : setLastT(TPL.t75,"    - (해당 없음)");
  reps.push([POS.biz_pE, POS.sec_end, bizXml]);

  // 3. 제안요약
  reps.push([POS.prop_pS, POS.prop_pE, setLastT(TPL.t75,"    - "+(data.proposal_summary||"해당 없음"))]);

  // 3-1. 제안표 데이터행 (첫 번째 제안만 - 원본에 1행)
  const prop0 = (data.proposals||[])[0]||{};
  POS.prop_row.forEach(([ps,pe],ci)=>{
    const vals=[prop0.title||"",prop0.person||"",prop0.date||""];
    reps.push([ps,pe,"<hp:t>"+ex(vals[ci])+"</hp:t>"]);
  });

  // 4. 원본 현안이슈
  reps.push([POS.origS_pE, POS.origE_pS, makeIssues(data.orig_issues,TPL.t14,TPL.t89)]);

  // 5. 인력동향
  const man=(data.manpower&&data.manpower.length?data.manpower:["특이사항 없음"]).map(m=>setLastT(TPL.t12,"  ○ "+m)).join("");
  reps.push([POS.sumE_pE, POS.manE_pS, man]);

  // 6. 요약 현안이슈
  reps.push([POS.sumS_pE, POS.sumE_pS, makeIssues(data.sum_issues,TPL.t14,TPL.t89)]);

  // 뒤→앞 정렬 후 적용
  reps.sort((a,b)=>b[0]-a[0]);
  for(const [f,t,c] of reps) xml=xml.slice(0,f)+c+xml.slice(t);

    return patchZip(origBuf, "Contents/section0.xml", xml);
}

exports.generateHWPX = functions
  .region("asia-northeast1")
  .runWith({memory:"512MB",timeoutSeconds:60})
  .https.onRequest(async(req,res)=>{
    res.set("Access-Control-Allow-Origin","*");
    res.set("Access-Control-Allow-Methods","POST,OPTIONS");
    res.set("Access-Control-Allow-Headers","Content-Type");
    if(req.method==="OPTIONS"){res.status(204).send("");return;}
    if(req.method!=="POST"){res.status(405).send("Method Not Allowed");return;}
    try{
      const {data}=req.body;
      const buf=buildHWPX(data||{});
      const fn=encodeURIComponent("일일상황보고_크리에이티브그룹.hwpx");
      res.set("Content-Type","application/octet-stream");
      res.set("Content-Disposition",`attachment; filename*=UTF-8''${fn}`);
      res.send(buf);
    }catch(e){
      console.error(e);
      res.status(500).json({error:e.message});
    }
  });
