// 페이지1 제안표 단일 데이터행 템플릿 (원본에서 추출)
let P1_ROW_TPL="";

function buildWeeklyHWPX(data){
  const origBuf=Buffer.from(WEEKLY_B64,"base64");
  let xml=readZip(origBuf,"Contents/section0.xml").toString("utf-8");
  const reps=[];
  // 제안표 단일 행 템플릿 추출 (17933~20362)
  P1_ROW_TPL=xml.slice(17933,20362);
  const rep=data.reporter||"";
  reps.push([POS_W.reporter1[0],POS_W.reporter1[1],"<hp:t>보고자 : "+ex(rep)+"</hp:t>"]);
  reps.push([POS_W.reporter2[0],POS_W.reporter2[1],"<hp:t>보고자 : "+ex(rep)+"</hp:t>"]);

  // 페이지1 연간목표 (3줄)
  const goalLines=(data.sumGoal||"").split("\n").map(s=>s.trim()).filter(Boolean);
  [[8588,8623],[8939,8980],[9299,9336]].forEach(([ps,pe],i)=>{
    reps.push([ps,pe,"<hp:t>"+ex(goalLines[i]||"")+"</hp:t>"]);
  });

  // 페이지1 진척사항 (2줄)
  const progLines=(data.sumProg||"").split("\n").map(s=>s.trim()).filter(Boolean);
  [[10128,10154],[10470,10506]].forEach(([ps,pe],i)=>{
    reps.push([ps,pe,"<hp:t>"+ex(progLines[i]||"")+"</hp:t>"]);
  });

  // 페이지2 연간목표 (3줄) - origGoal 사용
  const origGoalLines=(data.origGoal||data.sumGoal||"").split("\n").map(s=>s.trim()).filter(Boolean);
  [[87577,87612],[87928,87969],[88288,88325]].forEach(([ps,pe],i)=>{
    reps.push([ps,pe,"<hp:t>"+ex(origGoalLines[i]||"")+"</hp:t>"]);
  });

  // 페이지2 진척사항 (2줄) - origProg 사용
  const origProgLines=(data.origProg||data.sumProg||"").split("\n").map(s=>s.trim()).filter(Boolean);
  [[89117,89143],[89459,89495]].forEach(([ps,pe],i)=>{
    reps.push([ps,pe,"<hp:t>"+ex(origProgLines[i]||"")+"</hp:t>"]);
  });

  // 페이지2 제안요약 (91331~91363) - prop2_summary 사용
  const prop2SumText=ex(data.prop2_summary||data.prop_summary||"");
  if(prop2SumText) reps.push([91331,91363,"<hp:t>     · "+prop2SumText+"</hp:t>"]);

  // 이슈행 최대 4개 (초과분은 마지막 행에 이어붙임)
  const allIssues=data.sum_issues||[];
  const issueSlice=allIssues.slice(0,4);
  if(allIssues.length>4){
    const extra=allIssues.slice(4).map(i=>i.content).filter(Boolean).join(", ");
    if(issueSlice.length>0&&extra){
      issueSlice[issueSlice.length-1]={
        label:issueSlice[issueSlice.length-1].label,
        content:issueSlice[issueSlice.length-1].content+", "+extra
      };
    }
  }
  const issueXml=issueSlice.map(iss=>{
    const ts=[...TPL_W.issue.matchAll(/<hp:t>[^<]*<\/hp:t>/g)];
    if(ts.length>=3){
      return TPL_W.issue.slice(0,ts[1].index)+"<hp:t> "+ex(iss.label||"")+" </hp:t>"+
             TPL_W.issue.slice(ts[1].index+ts[1][0].length,ts[2].index)+
             "<hp:t>"+ex(iss.content||"")+"</hp:t>"+
             TPL_W.issue.slice(ts[2].index+ts[2][0].length);
    }
    return setLastT(TPL_W.issue,iss.content||"");
  }).join("");
  reps.push([POS_W.issue_s,POS_W.issue_e,issueXml]);

  // 제안요약 교체
  // 제안요약 - Firebase proposals.summary 우선 사용
  // 페이지1 제안요약 - prop_summary 우선 사용
  const propSumRaw = data.proposals&&data.proposals.length>0
    ? ("     · "+(data.prop_summary||ex(data.proposals.length)+"건 진행 예정"))
    : "     · 해당 없음";
  reps.push([POS_W.prop_sum[0],POS_W.prop_sum[1],"<hp:t>"+propSumRaw+"</hp:t>"]);

  // 페이지1 제안표 - 첫 행 교체 + 추가 행 삽입
  const allProps=data.proposals||[];
  const prop0=allProps[0]||{};
  POS_W.p1_r1.forEach(([ps,pe],ci)=>{
    const vals=[prop0.title||"",prop0.person||"",prop0.date||""];
    reps.push([ps,pe,"<hp:t>"+ex(vals[ci])+"</hp:t>"]);
  });
  // 2번째 이후 제안: setLastT로 각 셀 교체
  if(allProps.length>1){
    const extraRows=allProps.slice(1).map(p=>{
      let row=P1_ROW_TPL;
      const vals=[p.title||"",p.person||"",p.date||""];
      // 각 셀(subList)별로 순서대로 교체
      let ci=0;
      row=row.replace(/<hp:subList[^>]*>[\s\S]*?<\/hp:subList>/g,(cell)=>{
        if(ci>=3) return cell;
        const replaced=cell.replace(/<hp:t>[^<]*<\/hp:t>/,"<hp:t>"+ex(vals[ci])+"</hp:t>");
        ci++;
        return replaced;
      });
      return row;
    }).join("");
    reps.push([20362,20362,extraRows]);
  }
  reps.push([POS_W.collab[0],POS_W.collab[1],"<hp:t>"+ex(data.collab||"- 특이사항 없음")+"</hp:t>"]);
  [POS_W.p2_r1,POS_W.p2_r2].forEach((rowCells,ri)=>{
    const p=(data.proposals2||[])[ri]||{};
    rowCells.forEach(([ps,pe],ci)=>{
      reps.push([ps,pe,"<hp:t>"+ex([p.title||"",p.person||"",p.date||""][ci])+"</hp:t>"]);
    });
  });
  const bizXml=(data.biz_details||[]).map(b=>{
    const ts=[...TPL_W.bizName.matchAll(/<hp:t>[^<]*<\/hp:t>/g)];
    const nameRow=ts.length>=2
      ?TPL_W.bizName.slice(0,ts[1].index)+"<hp:t>"+ex(b.name||"")+" </hp:t>"+TPL_W.bizName.slice(ts[1].index+ts[1][0].length)
      :setLastT(TPL_W.bizName,b.name||"");
    return nameRow+(b.details||[]).map(d=>setLastT(TPL_W.bizDetail,"     · "+d)).join("");
  }).join("");
  reps.push([POS_W.biz_s,POS_W.biz_e,bizXml]);
  // 별첨 섹션: 없으면 제거, 있으면 유지
  // 23319: 별첨 텍스트 p 시작, 25796: 실제 별첨 표 시작
  // 별첨 제거 시 표(25796~81995) 전체 포함해서 제거
  if(!data.appendix||data.appendix.length===0){
    reps.push([22281,82204,""]); // 별첨 전체 제거 (22281~82204)
  }
  reps.sort((a,b)=>b[0]-a[0]);
  for(const [f,t,c] of reps) xml=xml.slice(0,f)+c+xml.slice(t);
  return patchZip(origBuf, "Contents/section0.xml", xml);
}

exports.generateWeeklyHWPX=functions.region("asia-northeast1").runWith({memory:"512MB",timeoutSeconds:60}).https.onRequest(async(req,res)=>{
  res.set("Access-Control-Allow-Origin","*");
  res.set("Access-Control-Allow-Methods","POST,OPTIONS");
  res.set("Access-Control-Allow-Headers","Content-Type");
  if(req.method==="OPTIONS"){res.status(204).send("");return;}
  if(req.method!=="POST"){res.status(405).send("Method Not Allowed");return;}
  try{
    const {data}=req.body;
    const buf=buildWeeklyHWPX(data||{});
    const fn=encodeURIComponent("주간상황보고_크리에이티브그룹.hwpx");
    res.set("Content-Type","application/octet-stream");
    res.set("Content-Disposition",`attachment; filename*=UTF-8''${fn}`);
    res.send(buf);
  }catch(e){console.error(e);res.status(500).json({error:e.message});}
});
